 intervene(tool,x,z){if(tool==='expand')return 'El territorio se descubre mediante la exploración de sus habitantes.';if(!Number.isFinite(x+z))return 'Elegí un punto sobre el planeta.';if(tool==='feed'){let n=0;for(let i=0;i<16;i++){const a=this.random()*6.28,r=this.random()*3.4;if(this.addFood({x:x+Math.cos(a)*r,z:z+Math.sin(a)*r},.12+this.random()*.25))n++;}if(!n)return 'Aquí no hay espacio para nuevos brotes.';this.log(n+' semillas comienzan a crecer.','♧','plant');this.pulses.push({x,z,type:tool,life:1});return 'Sembraste '+n+' semillas.';}if(tool==='rain'){this.rain=Math.max(this.rain,25);this.climate.moisture=clamp(this.climate.moisture+13,5,100);this.log('Una lluvia suave recorre el jardín.','☂','weather');return 'La lluvia devuelve humedad al mundo.';}if(tool==='mutate'){let best=null,d=7;for(const c of this.creatures){const dd=distance(c,{x,z});if(dd<d){d=dd;best=c;}}if(!best)return 'Acercá la chispa a una criatura.';const trait=mutateGenome(best.dna,()=>this.random());best.gene=best.dna.traits.size;best.hue=best.dna.traits.hue;best.life=SPECIES[best.species].longevity*best.dna.traits.longevity;best.named=true;this.log(best.name+': mutación de '+trait.toLowerCase()+'.','✧','mutation',best.id);this.pulses.push({x:best.x,z:best.z,type:tool,life:1});return trait+' cambió. La variante puede heredarse.';}}
 deposit(x,z,amount,source){if(amount<=0)return;this.nutrientsReturned+=amount;this.climate.fertility=clamp(this.climate.fertility+amount*.035,5,100);let patch=this.soil.find(p=>distance(p,{x,z})<2);if(patch){patch.nutrients+=amount;patch.total+=amount;}else{patch={x,z,nutrients:amount,total:amount,source,born:this.time};this.soil.push(patch);}if(this.soil.length>180){const old=this.soil.shift();this.soil[0].nutrients+=old.nutrients;this.soil[0].total+=old.nutrients;}}
